export function getDocTranslation(langCode = "en") {
  if (!langCode) return EXPORT_DOC_TRANSLATIONS.en;
  const raw = String(langCode).trim().toLowerCase();
  if (EXPORT_DOC_TRANSLATIONS[raw]) return EXPORT_DOC_TRANSLATIONS[raw];

  const normalized = raw.split("-")[0];
  if (EXPORT_DOC_TRANSLATIONS[normalized]) return EXPORT_DOC_TRANSLATIONS[normalized];

  // Try finding via translateCode alias from LANGUAGES
  const foundLang = LANGUAGES.find((l) => l.code.toLowerCase() === raw || l.code.toLowerCase() === normalized);
  if (foundLang && foundLang.translateCode) {
    const tCode = foundLang.translateCode.toLowerCase();
    if (EXPORT_DOC_TRANSLATIONS[tCode]) return EXPORT_DOC_TRANSLATIONS[tCode];
  }

  return EXPORT_DOC_TRANSLATIONS.en;
}

