export function translateDocValue(val, langCode = "en") {
  if (!val || typeof val !== "string") return val;
  const lang = String(langCode || "en").toLowerCase().split("-")[0];
  if (lang === "en") return val;

  const trimmed = val.trim();
  const lower = trimmed.toLowerCase();

  // Check direct value translations dictionary
  if (VALUE_TRANSLATIONS[lower] && VALUE_TRANSLATIONS[lower][lang]) {
    return VALUE_TRANSLATIONS[lower][lang];
  }

  // Check prefix / suffix / compound matches
  if (lower === "good condition." || lower === "good condition") {
    return (VALUE_TRANSLATIONS["good condition"] && VALUE_TRANSLATIONS["good condition"][lang]) || val;
  }
  if (lower === "lc" || lower === "letter of credit") {
    return (VALUE_TRANSLATIONS["letter of credit"] && VALUE_TRANSLATIONS["letter of credit"][lang]) || val;
  }
  if (lower === "cad" || lower === "cash against documents") {
    return (VALUE_TRANSLATIONS["cash against documents"] && VALUE_TRANSLATIONS["cash against documents"][lang]) || val;
  }
  if (lower === "t-shirts" || lower === "t-shirt") {
    return (VALUE_TRANSLATIONS["t-shirt"] && VALUE_TRANSLATIONS["t-shirt"][lang]) || val;
  }
  if (lower === "pcs" || lower === "pcs.") {
    return (VALUE_TRANSLATIONS["pcs"] && VALUE_TRANSLATIONS["pcs"][lang]) || val;
  }

  // Fallback to EXPORT_DOC_TRANSLATIONS
  const t = getDocTranslation(langCode);
  if (lower === "commercial" && t.val_commercial) return t.val_commercial;
  if (lower === "permanent" && t.val_permanent) return t.val_permanent;
  if (lower === "sample" && t.val_sample) return t.val_sample;
  if (lower === "temporary" && t.val_temporary) return t.val_temporary;
  if (lower === "bank transfer" && t.val_bank_transfer) return t.val_bank_transfer;
  if (lower === "india" && t.val_india) return t.val_india;
  if (lower === "air" && t.val_air) return t.val_air;
  if (lower === "sea" && t.val_sea) return t.val_sea;
  if (lower === "manager" && t.val_manager) return t.val_manager;
  if (lower === "authorized signatory" && t.authorized_signatory) return t.authorized_signatory;

  return val;
}

