export function formatAmountInWords(amountOrWords, currency = "USD", langCode = "en") {
  const lang = String(langCode || "en").toLowerCase().split("-")[0];
  const d = NUMBER_DICTS[lang] || NUMBER_DICTS.en;

  // If amount is a number or parseable number
  let num = Number(amountOrWords);
  if (!Number.isFinite(num) && typeof amountOrWords === "string") {
    // Try to extract numeric value from words if present
    const cleanNumStr = amountOrWords.replace(/[^0-9.]/g, "");
    if (cleanNumStr) num = Number(cleanNumStr);
  }

  if (!Number.isFinite(num) || num <= 0) {
    if (typeof amountOrWords === "string" && amountOrWords.trim()) {
      return amountOrWords.toUpperCase();
    }
    return `${currency} ${d.zero} ${d.only}`.toUpperCase();
  }

  const intPart = Math.floor(num);
  const decPart = Math.round((num - intPart) * 100);

  function convertGroup(val) {
    let str = "";
    if (val >= 100) {
      const hCount = Math.floor(val / 100);
      if (hCount === 1) {
        str += d.hundred + " ";
      } else {
        str += d.units[hCount] + " " + d.hundred + " ";
      }
      val %= 100;
    }
    if (val >= 20) {
      str += d.tens[Math.floor(val / 10)] + " ";
      val %= 10;
    }
    if (val > 0) {
      str += d.units[val] + " ";
    }
    return str.trim();
  }

  let words = "";
  let rem = intPart;

  if (rem >= 1000000000) {
    words += convertGroup(Math.floor(rem / 1000000000)) + " " + d.billion + " ";
    rem %= 1000000000;
  }
  if (rem >= 1000000) {
    words += convertGroup(Math.floor(rem / 1000000)) + " " + d.million + " ";
    rem %= 1000000;
  }
  if (rem >= 1000) {
    words += convertGroup(Math.floor(rem / 1000)) + " " + d.thousand + " ";
    rem %= 1000;
  }
  if (rem > 0) {
    words += convertGroup(rem) + " ";
  }

  words = words.trim();
  if (!words) words = d.zero;

  let result = `${currency} ${words}`;
  if (decPart > 0) {
    result += ` ${d.and} ${convertGroup(decPart)} ${d.cents}`;
  }
  result += ` ${d.only}`;
  return result.toUpperCase().replace(/\s+/g, " ").trim();
}

// ── Multi-Language Weight Info Helper ──────────────────────────────────────
export function getDocWeightInfo(totalNetKg = 0, selectedUnit = "GRAMS", langCode = "en") {
  const lang = String(langCode || "en").toLowerCase().split("-")[0];
  const unit = String(selectedUnit || "GRAMS").toUpperCase();

  const labels = {
    GRAMS: {
      en: "GRAMS", de: "GRAMM", fr: "GRAMMES", es: "GRAMOS", it: "GRAMMI", nl: "GRAM", pt: "GRAMAS", ru: "ГРАММЫ", pl: "GRAMY", tr: "GRAM",
      sq: "GRAMË", ca: "GRAMS", el: "ΓΡΑΜΜΑΡΙΑ", cs: "GRAMY", ro: "GRAME", hu: "GRAMM", da: "GRAM", fi: "GRAMMAA", sv: "GRAM",
      hr: "GRAMI", sr: "ГРАМИ", bg: "ГРАМИ", uk: "ГРАМИ", sk: "GRAMY", sl: "GRAMI", no: "GRAM", et: "GRAMMI", lv: "GRAMI", lt: "GRAMAI",
      ga: "GRAM", is: "GRÖMM", eu: "GRAMO", gl: "GRAMOS", hy: "ԳՐԱՄ", az: "QRAM", be: "ГРАМЫ", ka: "ᲒᲠᲐᲛᲘ", kk: "ГРАММ",
      mk: "ГРАМИ", bs: "GRAMI", lb: "GRAMM", mt: "GRAMMI", cy: "GRAM", gd: "GRAM", la: "GRAMMA", oc: "GRAMS",
      lux: "GRAMM", cnr: "ГРАМИ", nn: "GRAM", se: "GRAM"
    },
    KILOGRAMS: {
      en: "KILOGRAMS", de: "KILOGRAMM", fr: "KILOGRAMMES", es: "KILOGRAMOS", it: "CHILOGRAMMI", nl: "KILOGRAM", pt: "QUILOGRAMAS", ru: "КИЛОГРАММЫ", pl: "KILOGRAMY", tr: "KİLOGRAM",
      sq: "KILOGRAMË", ca: "QUILOGRAMS", el: "ΧΙΛΙΟΓΡΑΜΜΑ", cs: "KILOGRAMY", ro: "KILOGRAME", hu: "KILOGRAMM", da: "KILOGRAM", fi: "KILOGRAMMAA", sv: "KILOGRAM",
      hr: "KILOGRAMI", sr: "КИЛОГРАМИ", bg: "КИЛОГРАМИ", uk: "КІЛОГРАМИ", sk: "KILOGRAMY", sl: "KILOGRAMI", no: "KILOGRAM", et: "KILOGRAMMI", lv: "KILOGRAMI", lt: "KILOGRAMAI",
      ga: "CILEAGRAM", is: "KÍLÓGRÖMM", eu: "KILOGRAMO", gl: "QUILOGRAMOS", hy: "ԿԻԼՈԳՐԱՄ", az: "KILOQRAM", be: "КІЛАГРАМЫ", ka: "ᲙᲘᲚᲝᲒᲠᲐᲛᲘ", kk: "КИЛОГРАММ",
      mk: "КИЛОГРАМИ", bs: "KILOGRAMI", lb: "KILOGRAMM", mt: "KILOGRAMMI", cy: "CILOGRAM", gd: "CILEAGRAM", la: "CHILIOGRAMMA", oc: "KILOGRAMS",
      lux: "KILOGRAMM", cnr: "КИЛОГРАМИ", nn: "KILOGRAM", se: "KILOGRAM"
    },
    TONNES: {
      en: "TONNES", de: "TONNEN", fr: "TONNES", es: "TONELADAS", it: "TONNELLATE", nl: "TON", pt: "TONELADAS", ru: "ТОННЫ", pl: "TONY", tr: "TON",
      sq: "TONË", ca: "TONES", el: "ΤΟΝΝΟΙ", cs: "TUNY", ro: "TONE", hu: "TONNA", da: "TON", fi: "TONNIA", sv: "TON",
      hr: "TONE", sr: "ТОНЕ", bg: "ТОНА", uk: "ТОННИ", sk: "TONY", sl: "TONE", no: "TONN", et: "TONNI", lv: "TONNAS", lt: "TONOS",
      ga: "TONNA", is: "TONN", eu: "TONA", gl: "TONELADAS", hy: "ՏՈՆՆԱ", az: "TON", be: "ТОНЫ", ka: "ᲢᲝᲜᲐ", kk: "ТОННА",
      mk: "ТОНИ", bs: "TONE", lb: "TONNEN", mt: "TUNNELLATI", cy: "TUNNELL", gd: "TUNNA", la: "TONNA", oc: "TONES",
      lux: "TONNEN", cnr: "ТОНЕ", nn: "TONN", se: "TONN"
    }
  };

  const isKg = unit === "KILOGRAMS" || unit === "KGS" || unit === "KG";
  const isTonne = unit === "TONNES" || unit === "TONS" || unit === "TONNE";

  if (isKg) {
    const val = Number(totalNetKg || 0).toFixed(3);
    const unitLabel = (labels.KILOGRAMS[lang] || labels.KILOGRAMS.en);
    return {
      unitLabel,
      shortUnit: "kg",
      formattedValue: val,
      displayWithUnit: `${val} kg`,
    };
  }

  if (isTonne) {
    const tonnes = (Number(totalNetKg || 0) / 1000).toFixed(4);
    const unitLabel = (labels.TONNES[lang] || labels.TONNES.en);
    return {
      unitLabel,
      shortUnit: lang === "de" ? "t" : "Tonnes",
      formattedValue: tonnes,
      displayWithUnit: `${tonnes} ${lang === "de" ? "t" : "Tonnes"}`,
    };
  }

  // Default GRAMS
  const grams = (Number(totalNetKg || 0) * 1000).toFixed(0);
  const unitLabel = (labels.GRAMS[lang] || labels.GRAMS.en);
  return {
    unitLabel,
    shortUnit: "g",
    formattedValue: grams,
    displayWithUnit: `${grams} g`,
  };
}

